module ripple_carry_adder_sva (
    input logic       clk,
    input logic [3:0] A,
    input logic [3:0] B,
    input logic       Cin,
    input logic [3:0] S,
    input logic       Cout
);
    function automatic logic carry3(input logic x, input logic y, input logic z);
        carry3 = (x & y) | (y & z) | (x & z);
    endfunction

    // Bit 0 sum matches the first full adder XOR.
    check_sum_bit0: assert property (
        @(posedge clk) S[0] == (A[0] ^ B[0] ^ Cin)
    );

    // Bit 1 sum uses the carry generated by bit 0.
    check_sum_bit1: assert property (
        @(posedge clk) S[1] == (A[1] ^ B[1] ^ carry3(A[0], B[0], Cin))
    );

    // Bit 2 sum uses the carry propagated through bit 1.
    check_sum_bit2: assert property (
        @(posedge clk) S[2] == (A[2] ^ B[2] ^ carry3(A[1], B[1], carry3(A[0], B[0], Cin)))
    );

    // Bit 3 sum uses the carry propagated through bit 2.
    check_sum_bit3: assert property (
        @(posedge clk) S[3] == (A[3] ^ B[3] ^ carry3(A[2], B[2], carry3(A[1], B[1], carry3(A[0], B[0], Cin))))
    );

    // Carry out matches the final full adder carry.
    check_final_carry: assert property (
        @(posedge clk) Cout == carry3(A[3], B[3], carry3(A[2], B[2], carry3(A[1], B[1], carry3(A[0], B[0], Cin))))
    );

    // The full output equals 4-bit addition with carry in.
    check_full_result_value: assert property (
        @(posedge clk) {Cout, S} == ({1'b0, A} + {1'b0, B} + {4'b0000, Cin})
    );

    // Adding zero with no carry in preserves A.
    check_add_zero_to_a: assert property (
        @(posedge clk) (B == 4'b0000 && Cin == 1'b0) |-> ({Cout, S} == {1'b0, A})
    );

    // Adding zero with no carry in preserves B.
    check_add_zero_to_b: assert property (
        @(posedge clk) (A == 4'b0000 && Cin == 1'b0) |-> ({Cout, S} == {1'b0, B})
    );

    // A carry in increments the result when B is zero.
    check_increment_with_cin: assert property (
        @(posedge clk) (B == 4'b0000 && Cin == 1'b1) |-> ({Cout, S} == ({1'b0, A} + 5'b00001))
    );

endmodule